const order = $input.item.json;

order.customer = order.customer.trim();
order.email = order.email.toLowerCase();
order.amount = Number(order.amount);
order.vip = order.amount >= 100;

return order;

const items = $input.all();
const paid = items.filter(i => i.json.status === 'paid');
const total = paid.reduce((sum, i) => sum + i.json.amount, 0);
const { currency } = $('Shop settings').first().json;

return { date: $now.toISODate(), paid: paid.length, total, currency };
